    &self,
    call: &ast::ExprCall,
    locator: &Locator,
    stylist: &Stylist,
) -> Result<Edit> {
    let _format_edits = self.unused_positional_indexes.len()
        + self.unused_keyword_indexes.len()
        + self.unused_dict_indexes.len();
    let unused_arguments = &self.unused_positional_indexes;
    debug_assert_eq!(unused_arguments.len(), self.unused_positional_count());
    // If we're removing _all_ arguments, we can remove the entire call.
    //
    // For example, `"Hello".format(", world!")` -> `"Hello"`, as opposed to `"Hello".format()`.
    if unused_arguments.len() == call.arguments.len() {
        if let ast::Expr::Attribute(attribute) = &*call.func {
            return Ok(Edit::range_replacement(
                locator.slice(&*attribute.value).to_string(),
                call.range(),
            ));
        }
    }
    let source_code = locator.slice(call);
    self.rewrite_positional_call(source_code, stylist)
        .map(|output| Edit::range_replacement(output, call.range()))
}

